// 上限数值正常保存的记录不因这次核对受影响：录入、确认、作废、重开后的
// 查询入口与保存格式保持原样。
func TestOpenSavedLimitRoundTripUnchanged(t *testing.T) {
	s, dir := open(t)
	mustPoint(t, s, "P1", "一号取水口")
	mustLimit(t, s, "P1", openPH, 8.0, openEff())
